import{_ as e,o,c as n,ah as s}from"./chunks/framework.XbvJJa0u.js";const c=JSON.parse('{"title":"Fast Sky Component","description":"","frontmatter":{},"headers":[],"relativePath":"fast-sky-component.md","filePath":"fast-sky-component.md"}'),a={name:"fast-sky-component.md"};function r(i,t,h,d,p,l){return o(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="fast-sky-component" tabindex="-1">Fast Sky Component <a class="header-anchor" href="#fast-sky-component" aria-label="Permalink to “Fast Sky Component”">​</a></h1><p>The Fast Sky component is the main component of the Fast Sky system. It holds the core settings for the sky rendering.</p><p>The <a href="./setup#fast-sky-component">FastSkySceneConfig</a> component is optional, but recommended. It holds extra info such as moon transform, cloud shadow area, and it allows you to use <strong>astronomical positioning</strong> for the sun and moon.</p><p>The Fast Sky component works with the the SRP VolumeComponentSystem / PostProcessStack, thus allowing you to blend between different sky states depending on the camera&#39;s position or manually. See the <a href="./state-blending">State Blending</a> section for more info.</p><p>The position of the sun should be set in the <strong>Lighting Window</strong>. This can help prevent some issues that might occur when using multiple <strong>Directional Lights</strong>.</p><table tabindex="0"><thead><tr><th>Property</th><th>Function</th></tr></thead><tbody><tr><td>Enabled</td><td>Indicates if <strong>Fast Sky</strong> is enabled for this volume. Enabling this flag overrides the default unity skybox solution.</td></tr></tbody></table>',6)])])}const f=e(a,[["render",r]]);export{c as __pageData,f as default};
